  const [status, setStatus] = useState(path.includes("draft") ? "Drafts" : path.includes("sent") ? "Sent" : path.includes("approval") ? "Approvals" : "Queue");
  const [createTab, setCreateTab] = useState(path.includes("templates") ? "Templates" : path.includes("feeds") ? "Feeds" : "Ideas");
  const [ideaView, setIdeaView] = useState(new URLSearchParams(window.location.search).get("view")==="gallery"?"Gallery":"Board");
  const [communityTab, setCommunityTab] = useState(path.includes("mentions")||new URLSearchParams(window.location.search).get("tab")==="mentions" ? "Mentions" : "Comments");
  const [showAllPosts, setShowAllPosts] = useState(false);
