  useEffect(() => { writeLocal("postly-feeds", feeds); }, [feeds]);
  useEffect(() => { writeLocal("postly-tags", tags); }, [tags]);
  useEffect(() => { writeLocal("postly-saved-replies", savedReplies); }, [savedReplies]);
  useEffect(() => { writeLocal("postly-invites", invites); }, [invites]);
  useEffect(() => { writeLocal("postly-start-pages", startPages); }, [startPages]);
  useEffect(() => { writeLocal("postly-preferences", preferences); }, [preferences]);
  useEffect(() => { writeLocal("postly-notifications", notifications); }, [notifications]);
