  useEffect(() => { writeLocal("postly-beta-enabled", betaEnabled); }, [betaEnabled]);
  useEffect(() => { writeLocal("postly-role", role); }, [role]);
  useEffect(() => { writeLocal("postly-channel-access", channelAccess); }, [channelAccess]);
  useEffect(() => { writeLocal("postly-filters", filterSelections); }, [filterSelections]);
  useEffect(() => { writeLocal("postly-done-steps", doneSteps); }, [doneSteps]);
  useEffect(() => { writeLocal("postly-hide-queue-placeholder", hideQueuePlaceholder); }, [hideQueuePlaceholder]);
  useEffect(() => { writeLocal("postly-saved-pages", savedPages); }, [savedPages]);
  useEffect(() => {
    const onKeyDown = event => { if (event.key === "Escape") { setShowModal(""); setFilter(""); setNewMenuOpen(false); setOrgMenuOpen(false); } };
    const onPointerDown = event => { if (!event.target.closest(".pw-filter-row,.pw-range-wrap,.pw-template-toolbar,.pw-popover")) setFilter(""); if (!event.target.closest(".pw-new-wrap,.pw-popover")) setNewMenuOpen(false); if (!event.target.closest(".pw-org-wrap,.pw-popover")) setOrgMenuOpen(false); };
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onPointerDown);
    return () => { document.removeEventListener("keydown", onKeyDown); document.removeEventListener("pointerdown", onPointerDown); };
  }, []);
  useEffect(() => { setOrgDraft(organizationName); }, [organizationName]);
  const allChannels = channels.map(ch => ({ ...ch, connected: Boolean(socialStatus[ch.name.toLowerCase()]?.connected), available: connected.includes(ch.name) }));
  const channelRouteId = path.match(/^\/channels\/([^/]+)\/(?:schedule|settings)$/)?.[1];
  const channelRouteIndex = channels.findIndex(channel => channel.id === channelRouteId);
  const channelRoute = channelRouteIndex >= 0 ? channels[channelRouteIndex] : null;
  const recordsForView=records.filter(item=>(status==="Queue"?item.status==="scheduled":status==="Drafts"?item.status==="draft":status==="Sent"?item.status==="published":false)&&(!channelRoute||((item.channels||[]).includes(channelRouteIndex)))&&(!Object.entries(filterSelections).some(([key,enabled])=>enabled&&["Instagram","TikTok","YouTube"].includes(key))||(item.channels||[]).some(index=>filterSelections[channels[index]?.name]))&&(!Object.entries(filterSelections).some(([key,enabled])=>enabled&&tags.includes(key))||tags.filter(tag=>filterSelections[tag]).some(tag=>(item.productTags||"").split(/[, ]+/).includes(tag))));
  const channelSettingsPath = /^\/channels\/[^/]+\/settings$/.test(path);
